begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('f1100000-0000-0000-0000-000000000001','authenticated','authenticated','chat-a@example.test','',now(),'{}','{"name":"Chat A","company_name":"Chat QA A"}',now(),now()),
('f1100000-0000-0000-0000-000000000002','authenticated','authenticated','chat-b@example.test','',now(),'{}','{"name":"Chat B","company_name":"Chat QA B"}',now(),now()),
('f1100000-0000-0000-0000-000000000003','authenticated','authenticated','chat-c@example.test','',now(),'{}','{"name":"Chat C","company_name":"Chat QA C"}',now(),now());
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('chat.a',private.current_company_id(),true);
select set_config('chat.pid',(select id from public.profiles where auth_user_id=auth.uid() limit 1),true);
select set_config('chat.b',(select company_id from public.profiles where auth_user_id='f1100000-0000-0000-0000-000000000002' limit 1),true);
update public.profiles set company_id=current_setting('chat.a'),role='vendas' where auth_user_id='f1100000-0000-0000-0000-000000000003';
insert into public.products(id,company_id,name,active,catalog_active,pricing_type,sales_price) values('chat-product',current_setting('chat.a'),'Chat product',true,true,'unidade',10);
select ok(not has_table_privilege('anon','public.store_chat_messages','select'),'no public message SELECT');
select ok(not has_table_privilege('authenticated','public.store_chat_messages','insert'),'no forged message INSERT');
select ok(not has_table_privilege('authenticated','public.store_chat_messages','update'),'messages immutable to browser');
select ok(not has_table_privilege('authenticated','private.store_chat_sessions','select'),'token hashes not readable');
select ok(not has_function_privilege('authenticated','public.store_chat_visitor(text,text,uuid,text,jsonb)','execute'),'cannot forge service actor');
select ok(not has_function_privilege('anon','public.store_chat_inbox(uuid)','execute'),'anonymous cannot list inbox');
select is((select count(*)::integer from pg_publication_tables where pubname='supabase_realtime' and tablename in ('store_chat_conversations','store_chat_messages')),2,'realtime publication scoped to chat tables');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.store_chat_visitor(current_setting('chat.a'),repeat('a',64))->'conversation','null'::jsonb,'opening read does not create conversation');
select throws_ok(format($q$select public.store_chat_visitor(%L,'1',null,'read')$q$,current_setting('chat.a')),'P0001','Chat indisponível','enumerated token rejected');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('b',64),null,'create','{"content":"x","command_id":"f1100000-0000-0000-0000-000000000010","product_id":"chat-product"}')$q$,current_setting('chat.b')),'P0001','Contexto indisponível','cross tenant product rejected');
select set_config('chat.result',public.store_chat_visitor(current_setting('chat.a'),repeat('a',64),null,'create','{"content":"Olá 😊 ação <script>alert(1)</script>","command_id":"f1100000-0000-0000-0000-000000000010","product_id":"chat-product"}')::text,true);
select set_config('chat.cid',current_setting('chat.result')::jsonb#>>'{conversation,id}',true);
select is(current_setting('chat.result')::jsonb#>>'{conversation,status}','waiting','first message transitions open to waiting');
select is(jsonb_array_length(current_setting('chat.result')::jsonb->'messages'),2,'one greeting and one visitor message');
select is(current_setting('chat.result')::jsonb#>>'{messages,1,content}','Olá 😊 ação <script>alert(1)</script>','plain text preserves accents emoji and markup for escaped rendering');
select ok(not (current_setting('chat.result')::jsonb->'conversation' ?| array['company_id','customer_id','assigned_profile_id','token_hash']),'public conversation DTO minimizes internal fields');
select ok(not (current_setting('chat.result')::jsonb#>'{messages,1}' ?| array['company_id','sender_profile_id','conversation_id']),'public message DTO explicit');
select is((public.store_chat_visitor(current_setting('chat.a'),repeat('a',64),null,'create','{"content":"Olá 😊 ação <script>alert(1)</script>","command_id":"f1100000-0000-0000-0000-000000000010"}')->'messages'),current_setting('chat.result')::jsonb->'messages','create retry idempotent');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('a',64),null,'send','{"content":"changed","command_id":"f1100000-0000-0000-0000-000000000010"}')$q$,current_setting('chat.a')),'P0001','Comando já utilizado','replay mismatch rejected');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('a',64),null,'send',jsonb_build_object('content',repeat('x',2001),'command_id',gen_random_uuid()))$q$,current_setting('chat.a')),'P0001','Mensagem inválida','oversized message rejected');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('a',64),null,'send',jsonb_build_object('content','  ','command_id',gen_random_uuid()))$q$,current_setting('chat.a')),'P0001','Mensagem inválida','empty message rejected');
select is(public.store_chat_visitor(current_setting('chat.b'),repeat('a',64))->'conversation','null'::jsonb,'token cannot read other tenant');
select is(public.store_chat_visitor(current_setting('chat.a'),repeat('c',64))->'conversation','null'::jsonb,'other token cannot read conversation');
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(jsonb_array_length(public.store_chat_inbox()->'conversations'),1,'same tenant authorized inbox');
select is(public.store_chat_unread(),1::bigint,'unread counts visitor not system');
select lives_ok($$select public.store_chat_command('claim',current_setting('chat.cid')::uuid)$$,'claim succeeds');
select throws_ok($$select public.store_chat_command('claim',current_setting('chat.cid')::uuid)$$,'P0001','A conversa já foi assumida ou encerrada','second claim does not overwrite winner');
select lives_ok($$select public.store_chat_command('read',current_setting('chat.cid')::uuid,'{"seq":2}')$$,'read cursor stored separately');
select is(public.store_chat_unread(),0::bigint,'read clears unread');
select lives_ok($$select public.store_chat_command('read',current_setting('chat.cid')::uuid,'{"seq":1}')$$,'older cursor accepted monotonically');
select is(public.store_chat_unread(),0::bigint,'old cursor never marks read message unread');
select lives_ok($$select public.store_chat_command('send',current_setting('chat.cid')::uuid,'{"content":"Equipe: olá!","command_id":"f1100000-0000-0000-0000-000000000020"}')$$,'assigned agent reply');
select lives_ok($$select public.store_chat_command('send',current_setting('chat.cid')::uuid,'{"content":"Equipe: olá!","command_id":"f1100000-0000-0000-0000-000000000020"}')$$,'agent retry is idempotent');
select is(jsonb_array_length(public.store_chat_inbox(current_setting('chat.cid')::uuid)->'messages'),3,'reply not duplicated');
select lives_ok($$select public.store_chat_command('quick_reply',null,'{"title":"Saudação","content":"Olá QA"}')$$,'admin creates quick reply');
select lives_ok($$select public.store_chat_command('settings',null,'{"greeting":"Boas-vindas","away_message":"Responderemos em nosso horário."}')$$,'admin updates greeting');
select is(public.store_chat_inbox()#>>'{settings,greeting}','Boas-vindas','tenant greeting persisted');
reset role;
select set_config('chat.target',(select id from public.profiles where auth_user_id='f1100000-0000-0000-0000-000000000003' limit 1),true);
set local role authenticated;
select lives_ok($$select public.store_chat_command('transfer',current_setting('chat.cid')::uuid,jsonb_build_object('profile_id',current_setting('chat.target'),'expected_profile_id',current_setting('chat.pid')))$$,'transfer eligible same tenant');
select throws_ok($$select public.store_chat_command('transfer',current_setting('chat.cid')::uuid,jsonb_build_object('profile_id',current_setting('chat.target'),'expected_profile_id',current_setting('chat.pid')))$$,'P0001','Transferência indisponível ou conflito','stale transfer CAS fails');
select throws_ok($$select public.store_chat_command('send',current_setting('chat.cid')::uuid,jsonb_build_object('content','x','command_id',gen_random_uuid()))$$,'P0001','Assuma o atendimento antes de responder','old assignee cannot reply');
select lives_ok($$select public.store_chat_command('close',current_setting('chat.cid')::uuid)$$,'manager closes conversation');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.store_chat_visitor(current_setting('chat.a'),repeat('a',64),null,'send','{"content":"Retorno QA","command_id":"f1100000-0000-0000-0000-000000000030"}')#>>'{conversation,status}','waiting','visitor reopens within session');
select is((select assigned_profile_id from public.store_chat_conversations where id=current_setting('chat.cid')::uuid),null,'reopen clears stale assignment');
select ok((select count(*)=1 from public.audit_logs where company_id=current_setting('chat.a') and action='chat.conversation_transferred'),'transfer audited once');
select is((select count(*)::integer from public.audit_logs where company_id=current_setting('chat.a') and action like 'chat.%message%'),0,'individual messages not placed in enterprise audit');
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::integer from public.store_chat_messages),0,'cross tenant message RLS');
select throws_ok($$select public.store_chat_command('claim',current_setting('chat.cid')::uuid)$$,'P0001','Conversa indisponível','cross tenant claim denied');
reset role;
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
insert into public.role_permissions(company_id,path,roles) values(current_setting('chat.a'),'/attendance',array[]::text[]);
set local role authenticated;
select throws_ok($$select public.store_chat_inbox()$$,'42501','Atendimento não autorizado','configured deny includes admin');
select is((select count(*)::integer from public.store_chat_messages),0,'configured deny applied to realtime SELECT');
reset role;
delete from public.role_permissions where company_id=current_setting('chat.a') and path='/attendance';
update private.store_chat_sessions set expires_at=now()-interval '1 second' where token_hash=repeat('a',64);
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('a',64))$q$,current_setting('chat.a')),'42501','Sessão de atendimento expirada','expired session cannot read');
-- Verified customer/order context, account switching and logout boundaries.
insert into public.customers(id,company_id,name,document) values('chat-customer',current_setting('chat.a'),'Customer QA',''),('chat-other-customer',current_setting('chat.a'),'Other customer QA','');
insert into public.store_customer_accounts(id,company_id,customer_id,auth_user_id,status) values('chat-account',current_setting('chat.a'),'chat-customer','f1100000-0000-0000-0000-000000000002','active');
insert into public.orders(id,company_id,customer_id,customer_name,number,status,deadline) values('chat-order',current_setting('chat.a'),'chat-customer','Customer QA','PED-111F','aguardando_pagamento',current_date),('chat-other-order',current_setting('chat.a'),'chat-other-customer','Other QA','PED-112F','aguardando_pagamento',current_date);
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('d',64),null,'create','{"content":"Order","command_id":"f1100000-0000-0000-0000-000000000040","order_id":"chat-order"}')$q$,current_setting('chat.a')),'P0001','Contexto indisponível','anonymous cannot claim order by ID');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('d',64),'f1100000-0000-0000-0000-000000000002','create','{"content":"Order","command_id":"f1100000-0000-0000-0000-000000000040","order_id":"chat-other-order"}')$q$,current_setting('chat.a')),'P0001','Contexto indisponível','authenticated customer cannot use another customer order');
select set_config('chat.customer_result',public.store_chat_visitor(current_setting('chat.a'),repeat('d',64),'f1100000-0000-0000-0000-000000000002','create','{"content":"Order QA","command_id":"f1100000-0000-0000-0000-000000000040","order_id":"chat-order"}')::text,true);
select is(current_setting('chat.customer_result')::jsonb#>>'{conversation,order_id}','chat-order','owned order context accepted');
select is(current_setting('chat.customer_result')::jsonb#>>'{messages,1,sender_type}','customer','sender derived from verified account');
select is((select customer_id from public.store_chat_conversations where id=(current_setting('chat.customer_result')::jsonb#>>'{conversation,id}')::uuid),'chat-customer','canonical customer linked');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('d',64))$q$,current_setting('chat.a')),'42501','Sessão de atendimento expirada','logout cannot read customer conversation through residual cookie');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('d',64),'f1100000-0000-0000-0000-000000000001')$q$,current_setting('chat.a')),'42501','Sessão de atendimento expirada','account switch denied');
update public.store_customer_accounts set status='blocked' where id='chat-account';
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('d',64),'f1100000-0000-0000-0000-000000000002')$q$,current_setting('chat.a')),'42501','Sessão de atendimento expirada','deactivated customer account denied');
update public.store_customer_accounts set status='active' where id='chat-account';
select lives_ok(format($q$select public.store_chat_visitor(%L,repeat('e',64),null,'create',jsonb_build_object('content','Anonymous QA','command_id',gen_random_uuid()))$q$,current_setting('chat.a')),'new anonymous session');
select lives_ok(format($q$select public.store_chat_visitor(%L,repeat('e',64),'f1100000-0000-0000-0000-000000000002')$q$,current_setting('chat.a')),'later login links existing anonymous conversation server-side');
select is((select cv.customer_id from public.store_chat_conversations cv join private.store_chat_sessions s on s.conversation_id=cv.id where s.token_hash=repeat('e',64)),'chat-customer','anonymous upgrade links same canonical customer');
select is((select count(*)::integer from public.customers where company_id=current_setting('chat.a')),2,'chat never creates extra customers');
-- Flood control is serialized under conversation lock.
select lives_ok(format($q$do $f$begin for i in 1..11 loop perform public.store_chat_visitor(%L,repeat('e',64),'f1100000-0000-0000-0000-000000000002','send',jsonb_build_object('content','Flood QA '||i,'command_id',gen_random_uuid()));end loop;end $f$$q$,current_setting('chat.a')),'up to 12 visitor messages/minute');
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('e',64),'f1100000-0000-0000-0000-000000000002','send',jsonb_build_object('content','Over cap','command_id',gen_random_uuid()))$q$,current_setting('chat.a')),'P0001','Aguarde antes de enviar mais mensagens','13th visitor message blocked');
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.store_chat_command('quick_reply',null,(public.store_chat_inbox()#>'{quick_replies,0}')||'{"content":"Edited QA","active":false}')$$,'quick reply edit and deactivate uses CAS');
select is(public.store_chat_inbox()#>>'{quick_replies,0,active}','false','inactive reply retained in history');
select throws_ok($$select public.store_chat_command('quick_reply',null,(public.store_chat_inbox()#>'{quick_replies,0}')||'{"revision":1}')$$,'P0001','Conflito: atualize antes de salvar','stale quick reply CAS rejected');
select is(public.save_quote_with_items_phase4b(jsonb_build_object('id','chat-quote','company_id',current_setting('chat.a'),'customer_id','chat-customer','customer_name','Customer QA','status','rascunho','total_amount',10,'discount',0,'valid_until',current_date+15,'notes','QA canonical','chat_conversation_id',(current_setting('chat.customer_result')::jsonb#>>'{conversation,id}')),'[{"id":"chat-quote-item","product_id":"chat-product","product_name":"Chat product","quantity":1,"unit_price":10,"total_price":10}]')->>'result_status','UPDATED','canonical reviewed quote save succeeds');
select is(public.store_chat_inbox()#>>'{metrics,quotes}','1','only successful canonical save counts conversion');
select lives_ok($$delete from public.quotes where id='chat-quote' and company_id=current_setting('chat.a') and updated_at=(select updated_at from public.quotes where id='chat-quote')$$,'canonical CAS quote delete remains available after chat conversion');
select is(public.store_chat_inbox()#>>'{metrics,quotes}','1','historical conversion retained after quote delete without blocking canonical workflow');
reset role;
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.store_chat_command('settings',null,'{"greeting":"forged","away_message":"forged"}')$$,'P0001','Somente administradores','sales agent cannot change tenant settings');
select lives_ok($$delete from public.products where id='chat-product' and company_id=current_setting('chat.a')$$,'chat context does not block canonical product deletion');
select lives_ok($$delete from public.orders where id='chat-order' and company_id=current_setting('chat.a')$$,'chat context does not block canonical order deletion');
select is((select count(*)::integer from public.store_chat_conversations where company_id=current_setting('chat.a') and product_id='chat-product'),0,'deleted product context safely unlinked');
select is((select count(*)::integer from public.store_chat_conversations where company_id=current_setting('chat.a') and order_id='chat-order'),0,'deleted order context safely unlinked');
reset role;
-- A removed assignee must leave an operable conversation, never a stranded inbox row.
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values('f1100000-0000-0000-0000-000000000004','authenticated','authenticated','chat-d@example.test','',now(),'{}','{"name":"Chat D","company_name":"Chat QA D"}',now(),now());
update public.profiles set company_id=current_setting('chat.a'),role='vendas' where auth_user_id='f1100000-0000-0000-0000-000000000004';
update public.store_chat_conversations set assigned_profile_id=(select id from public.profiles where auth_user_id='f1100000-0000-0000-0000-000000000004'),status='in_progress' where id=current_setting('chat.cid')::uuid;
delete from public.profiles where auth_user_id='f1100000-0000-0000-0000-000000000004';
select set_config('request.jwt.claims','{"sub":"f1100000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.store_chat_command('claim',current_setting('chat.cid')::uuid)$$,'active agent can reclaim in_progress conversation after assignee deletion');
select is((select assigned_profile_id from public.store_chat_conversations where id=current_setting('chat.cid')::uuid),current_setting('chat.target'),'claim restores eligible assignee');
reset role;
-- Existing Billing lifecycle is reused, not bypassed by new tables/RPCs.
insert into public.saas_subscriptions(company_id,plan_id,status,billing_cycle,provider_subscription_id,current_period_start,current_period_end,contract)
select current_setting('chat.a'),id,'expired','monthly','chat-mock-billing',now()-interval '1 month',now()-interval '1 day',jsonb_build_object('features',features) from public.saas_plans where code='qa-complete';
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok(format($q$select public.store_chat_visitor(%L,repeat('f',64),null,'create',jsonb_build_object('content','Blocked','command_id',gen_random_uuid()))$q$,current_setting('chat.a')),'42501','Billing: Assinatura em modo somente leitura. Seus dados e exportações estão preservados.','expired Billing blocks incoming creation');
select lives_ok(format($q$select public.store_chat_visitor(%L,repeat('d',64),'f1100000-0000-0000-0000-000000000002')$q$,current_setting('chat.a')),'expired Billing preserves public history');
select * from finish();
rollback;
